<script setup>
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { currentUser } from '../data/user'
import { useRoleMenu } from '../composables/useRoleMenu'
import { useProfilePhoto } from '../composables/profilePhoto'
import { session } from '../data/session'
import { notifyError, notifySuccess } from '../composables/toast'
import BottomNav from '../components/BottomNav.vue'

const router = useRouter()
const { roleLabel } = useRoleMenu()
const showLogoutConfirm = ref(false)
const showPhotoActions = ref(false)
const profilePhotoInput = ref(null)
const uploadingPhoto = ref(false)
const { profilePhotoUrl, photoFailed, reloadProfilePhoto } = useProfilePhoto()

const PROFILE_API = 'juragan.api.portal.roles'
const MAX_PROFILE_PHOTO_BYTES = 5 * 1024 * 1024

function onProfilePhotoClick() {
	if (uploadingPhoto.value) return
	if (currentUser.userImage) {
		showPhotoActions.value = true
		return
	}
	openProfilePhotoPicker()
}

function openProfilePhotoPicker() {
	if (uploadingPhoto.value || !profilePhotoInput.value) return
	showPhotoActions.value = false
	profilePhotoInput.value.value = ''
	profilePhotoInput.value.click()
}

function responseError(json, status) {
	const message = typeof json?.message === 'string' ? json.message : `HTTP ${status}`
	return Object.assign(new Error(message), json || {})
}

async function onProfilePhotoChange(event) {
	const file = event.target.files?.[0]
	if (!file) return
	if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) {
		notifyError('Format foto harus JPG, PNG, atau WebP.', 'Foto tidak valid')
		return
	}
	if (file.size > MAX_PROFILE_PHOTO_BYTES) {
		notifyError('Ukuran foto maksimal 5 MB.', 'Foto terlalu besar')
		return
	}

	uploadingPhoto.value = true
	try {
		const body = new FormData()
		body.append('file', file, file.name)
		const res = await fetch(`/api/method/${PROFILE_API}.upload_my_profile_photo`, {
			method: 'POST',
			credentials: 'include',
			headers: {
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body,
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw responseError(json, res.status)

		const nextImage = json.message?.user_image || ''
		if (nextImage === currentUser.userImage) {
			// Deduplikasi File bisa menghasilkan URL yang sama.
			await reloadProfilePhoto(nextImage)
		} else {
			// Watcher akan mengambil isi foto baru lewat endpoint terautentikasi.
			currentUser.userImage = nextImage
		}
		notifySuccess('Foto profil berhasil diperbarui.')
	} catch (e) {
		notifyError(e, 'Gagal mengubah foto')
	} finally {
		uploadingPhoto.value = false
	}
}

async function deleteProfilePhoto() {
	if (uploadingPhoto.value) return
	showPhotoActions.value = false
	uploadingPhoto.value = true
	try {
		const res = await fetch(`/api/method/${PROFILE_API}.delete_my_profile_photo`, {
			method: 'POST',
			credentials: 'include',
			headers: {
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw responseError(json, res.status)

		currentUser.userImage = ''
		await reloadProfilePhoto('')
		notifySuccess('Foto profil berhasil dihapus.')
	} catch (e) {
		notifyError(e, 'Gagal menghapus foto')
	} finally {
		uploadingPhoto.value = false
	}
}

// Tiga halaman detail Master Karyawan milik user yang sedang login (hanya-baca).
const detailMenu = [
	{ label: 'Personal Details', route: 'ProfilPersonal' },
	{ label: 'Education Details', route: 'ProfilEducation' },
	{ label: 'Bank Details', route: 'ProfilBank' },
]

async function confirmLogout() {
	await session.doLogout()
}
</script>
